save(384,dict(paragraphs=["Subash Singh Parajuli is a poet and literary organiser from Nepal. His poetry collections include Mystic Myth, Soil on Pyre and Symphony of Life, and he has also worked on the international anthology Pandemic Poetry 2020. In a 2024 interview with The Hemingway Post, he described translation, cultural exchange and workshops as ways to bring Nepali poetry to a wider readership.","‘While searching for the peace’ repeatedly measures the promise of peace against greed, exploitation and failures of human care. Its refrain moves through religion, luxury, science and intimate relationships, building a restless public lament. The accompanying ‘An untold tale of street’ in the March contribution narrows that concern to an abandoned child, using the responses of trees, birds and dogs to expose the absence of human protection."],sources=[source('Elmawja — Subash Singh Parajuli','https://elmawja.com/subash-singh-parajuli-nepal/','Opened contributor biography lines250–252: Nepal, literary organiser, three poetry books and anthology editing.'),source('The Hemingway Post — interview with Subash Singh Parajuli','https://thpnepal.blogspot.com/2024/05/an-interview-with-subash-singh-parajuli.html','Full indexed interview of May29 2024, first-person discussion of translation, exchange and workshops. Direct open timeout.','search_index'),source('Exotic India — Symphony of Life',u,'Indexed book catalogue identifies author, Brosis, 2019, English, ISBN9789388519168. Direct open cache miss.','search_index')],books=[dict(title='Symphony of Life',detail='English poetry. Brosis Publishers and Distributors, 2019. ISBN 9789388519168.',url=u)],identity_match='Exact name, Nepal, poetry and travel/literary activity in contributor bio match captured profile; three collections named and book catalogue confirms one.',poems_read=[dict(id=526,title='While searching for the peace………….',coverage='Entire original including embedded An untold tale of street.',basis='Peace refrain versus corruption/abuse; second poem abandoned child, disappearance and caged nestlings.'),dict(id=552,title='While searching for the peace………….',coverage='Entire May original.',basis='Repeats peace poem from526 without the embedded street poem; not counted as a distinct thematic work.')],limitations=['526 is a composite text and 552 repeats its main poem; preserved without merge or reinterpretation of contribution counts.','Educator/eastern Nepal details remain supplied-biography only; no current employer added.','Specific award organisations and prestige not independently corroborated; no award assertions added.','Books identified bibliographically, not read in full; anthology editorial role distinguished from sole authorship.'],research_leads=[dict(url='https://thuprai.com/author/subash-singh-parajuli/',finding='Index links Pandemic Poetry2020 but labels authored; other sources say edited. No sole-author claim made.')],next_action='Independent author/editor review including composite/repeated source structure and specific award documentation.'))
